import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"多账户交易","description":"","frontmatter":{},"headers":[],"relativePath":"features/multi-account.md","filePath":"features/multi-account.md","lastUpdated":null}'),d={name:"features/multi-account.md"};function e(s,t,i,n,u,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="多账户交易" tabindex="-1">多账户交易 <a class="header-anchor" href="#多账户交易" aria-label="Permalink to &quot;多账户交易&quot;">​</a></h1><p>Northstar 的多账户模型非常简洁：<strong>网关即账户</strong>。每创建一个用途为&quot;交易&quot;的网关，就接入了一个实际交易账户；创建任意多个交易网关，即可在一个平台内统一管理多个账户（不同期货公司、不同市场、模拟与实盘混管均可）。</p><h2 id="一、接入多个账户" tabindex="-1">一、接入多个账户 <a class="header-anchor" href="#一、接入多个账户" aria-label="Permalink to &quot;一、接入多个账户&quot;">​</a></h2><p>在 <strong>网关管理</strong> 中为每个账户创建交易网关：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>网关渠道</td><td>CTP（期货实盘）/ TIGER / OKX / BIAN / SIM（模拟）等</td></tr><tr><td>网关用途</td><td><strong>交易</strong></td></tr><tr><td>行情网关</td><td>为该账户绑定一个行情网关（行情与交易分离，可多个账户共享一个行情网关）</td></tr><tr><td>连线方式</td><td>建议开启<strong>自动连线</strong>，平台启动后自动连接</td></tr><tr><td>网关配置</td><td>各渠道的账户凭据等配置，在&quot;网关配置&quot;弹窗中按动态表单填写</td></tr></tbody></table><p>每个网关卡片独立显示连接状态（已连接/已断开，行情网关另有&quot;行情：活跃/不活跃&quot;标签），可分别 <strong>连线 / 断开</strong>，互不影响。</p><div class="tip custom-block"><p class="custom-block-title">典型组合</p><ul><li>期货公司 A 账户 + 期货公司 B 账户：两个 CTP 交易网关共享一个 CTP 行情网关；</li><li>模拟账户与实盘账户并存：SIM 网关练手，CTP 网关跑实盘，互不影响。</li></ul></div><h2 id="二、交易面板多账户切换" tabindex="-1">二、交易面板多账户切换 <a class="header-anchor" href="#二、交易面板多账户切换" aria-label="Permalink to &quot;二、交易面板多账户切换&quot;">​</a></h2><p>底部交易面板的 <strong>交易账户</strong> 下拉列出全部交易网关。切换账户后：</p><ul><li>账户权益 / 可用金额 / 资金使用率；</li><li>持仓、挂单、计划、委托、成交五个标签页；</li></ul><p>全部切换为该账户的数据，下单请求也发往该账户。多账户手工交易只需一次切换。</p><h2 id="三、一个模组驱动多个账户" tabindex="-1">三、一个模组驱动多个账户 <a class="header-anchor" href="#三、一个模组驱动多个账户" aria-label="Permalink to &quot;三、一个模组驱动多个账户&quot;">​</a></h2><p>新建/修改模组时，<strong>绑定账户</strong> 是多选框 —— 选一个策略同时绑定多个交易账户，模组会按&quot;合约 → 账户&quot;的映射把信号分发到各个账户下单。</p><p>这是多账户程序化交易的核心用法：</p><ul><li><strong>一套策略，多账户复制</strong>：同一信号在多个账户同步执行，无需为每个账户单独建模组；</li><li><strong>模组账户独立记账</strong>：模组内部有自己的逻辑账本（模组账户），按&quot;分配金额&quot;控制风险，与各实际账户资金解耦。</li></ul><div class="info custom-block"><p class="custom-block-title">分配金额的作用</p><p>模组的&quot;分配金额&quot;是模组账户的额度，决定策略能动用多少资金，与账户实际余额无关。多账户场景下，可用&quot;分配金额 + 默认下单量&quot;统一控制每个账户的交易规模。</p></div><h2 id="四、合约配置" tabindex="-1">四、合约配置 <a class="header-anchor" href="#四、合约配置" aria-label="Permalink to &quot;四、合约配置&quot;">​</a></h2><p><strong>合约配置</strong> 菜单按合约维度设置交易参数，支持批量操作与导入导出：</p><ul><li><strong>杠杆 / 保证金</strong>：影响资金占用计算；</li><li><strong>手续费</strong>：影响绩效统计的准确性；</li><li><strong>交易时段</strong>：影响交易时间判断。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>仅 <strong>PLAYBACK</strong>（回放）网关的合约支持自定义保证金与手续费（用于回测假设）；实盘渠道的合约参数由网关接入时确定。</p></div><h2 id="五、多账户行情总览" tabindex="-1">五、多账户行情总览 <a class="header-anchor" href="#五、多账户行情总览" aria-label="Permalink to &quot;五、多账户行情总览&quot;">​</a></h2><p><strong>交易中心 → 活跃行情报价</strong>（<code>Alt+8</code>）以表格汇总所有行情网关的实时报价：</p><ul><li>列：名称、最新价、涨跌、涨幅%、成交量、持仓量、日增仓、报价时间；</li><li>可按 <strong>行情网关</strong> 筛选（全部 / 指定渠道），按合约名或代码搜索；</li><li>支持分页（10 ~ 100 条/页）。</li></ul><p>多账户各自绑定了不同行情网关时，可在此统一盯盘。</p><h2 id="六、多账户使用建议" tabindex="-1">六、多账户使用建议 <a class="header-anchor" href="#六、多账户使用建议" aria-label="Permalink to &quot;六、多账户使用建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐做法</th></tr></thead><tbody><tr><td>手工同时盯多个账户</td><td>交易面板切换账户 + 活跃行情报价统一盯盘</td></tr><tr><td>同一策略跑多个账户</td><td>一个模组绑定多个账户</td></tr><tr><td>不同策略跑不同账户</td><td>每&quot;策略 × 账户组合&quot;建一个模组，用模组名称区分</td></tr><tr><td>实盘前验证</td><td>先用 SIM 账户跑&quot;模拟盘&quot;模组，再切换到实盘账户建&quot;实盘&quot;模组</td></tr><tr><td>风险控制</td><td>为每个模组设定独立的分配金额，模组间资金互相隔离</td></tr></tbody></table>',26)])])}const g=o(d,[["render",e]]);export{p as __pageData,g as default};
